mapper.select:
select to_char(expires_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"') exp, to_char((created_at + make_interval(hours => #{maxH})) at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"') maxat,
       greatest(0, floor(extract(epoch from expires_at - now())))::int remain, case when work_until > now() then to_char(work_until at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"') end wu, work_reason
  from sessions where id = #{id}
